bigint_plain.source:
const nf = new Intl.NumberFormat('en-US'); const parts = (v) => v.map(p => p.type + ':' + p.value).join('|');
return { bigint: nf.format(9007199254740993n), str: nf.format('9007199254740993'), huge: nf.format(123456789012345678901234567890n), neg: nf.format(-9007199254740993n),
  parts: parts(nf.formatToParts(9007199254740993n)), strParts: parts(nf.formatToParts('9007199254740993')), range: nf.formatRange(1234567, 1234999),
  rangeBig: nf.formatRange(9007199254740993n, 9007199254740999n), rangeParts: parts(nf.formatRangeToParts(1234567, 1234999)) };

native_bigint_currency_compact.source:
const parts = (v) => v.map(p => p.type + ':' + p.value).join('|');
const cur = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }); const compact = new Intl.NumberFormat('en-US', { notation: 'compact' }); const pct = new Intl.NumberFormat('en-US', { style: 'percent' });
return { cur: cur.format(9007199254740993n), curParts: parts(cur.formatToParts(9007199254740993n)), compact: compact.format(1234567890123456789n), compactParts: parts(compact.formatToParts(1234567890123456789n)), pct: pct.format(123n) };

day_period_en_us.source:
const times = [[0, 0, 0], [0, 30, 0], [3, 5, 0], [6, 0, 0], [9, 15, 0], [12, 0, 0], [12, 0, 30], [12, 30, 0], [15, 45, 10], [18, 0, 0], [21, 0, 0], [23, 59, 59]];
const combos = [{}, { hour: 'numeric' }, { hour: 'numeric', minute: 'numeric' }, { hour: 'numeric', hour12: true }, { hour: 'numeric', minute: 'numeric', second: 'numeric', hour12: true }];
const out = {};
for (const loc of ['en-US']) for (const w of ['narrow', 'short', 'long']) combos.forEach((c, ci) => {
  const f = new Intl.DateTimeFormat(loc, Object.assign({ dayPeriod: w, timeZone: 'UTC' }, c));
  out[loc + '/' + w + '/' + ci] = times.map(t => f.format(new Date(Date.UTC(2020, 0, 1, t[0], t[1], t[2])))).join('|');
});
return out;

