native_day_period_resolved.source:
const r = (loc, o) => { const x = new Intl.DateTimeFormat(loc, Object.assign({ timeZone: 'UTC' }, o)).resolvedOptions(); return [x.hourCycle, x.dayPeriod === undefined ? null : x.dayPeriod]; };
let bad; try { new Intl.DateTimeFormat('en-US', { dayPeriod: 'bogus' }); bad = 'no error'; } catch (e) { bad = e.name; }
return { us: r('en-US', { dayPeriod: 'long', hour: 'numeric' }), gb: r('en-GB', { dayPeriod: 'long', hour: 'numeric' }), gb12: r('en-GB', { dayPeriod: 'long', hour: 'numeric', hour12: true }), bad };
